const LOG_DISPLAY_MODES=[`all`,`stderr`,`sandbox`,`none`],LOG_DISPLAY_MODE_CYCLE=[`none`,`all`,`stderr`,`sandbox`];function parseLogDisplayMode(t){return LOG_DISPLAY_MODES.find(e=>e===t)}function nextLogDisplayMode(e){let n=LOG_DISPLAY_MODE_CYCLE.indexOf(e);return LOG_DISPLAY_MODE_CYCLE[(n+1)%LOG_DISPLAY_MODE_CYCLE.length]??`none`}export{LOG_DISPLAY_MODES,LOG_DISPLAY_MODE_CYCLE,nextLogDisplayMode,parseLogDisplayMode};